26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** A building block of 3 alike components is offered at this base premium. */
68	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
69	const COMPONENT_BLOCK_SIZE = 3;
70	
71	const COMPONENT_TYPES = ["rune", "moonstone"];
72	
73	const countByType = (items: Item[]): Map<string, number> => {
74	  const counts = new Map<string, number>();
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	  return counts;
79	};
80	
81	/**
82	 * A group of exactly 3 alike components is priced as one block. "Alike" means
83	 * the same type, and the block does not repeat: 4 or 7 runes are each priced
84	 * per item.
85	 */
86	const groupBasePremium = (type: string, count: number): number =>
87	  COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE
88	    ? COMPONENT_BLOCK_BASE_PREMIUM
89	    : count * BASE_PREMIUMS[type];
90	
91	const sumOfItemPremiums = (items: Item[]): number =>
92	  [...countByType(items)].reduce(
93	    (sum, [type, count]) => sum + groupBasePremium(type, count),
94	    0,
95	  );
96	
97	export const runScenario = (scenario: Scenario): ScenarioResult => {
98	  const quote = scenario.steps[0] as QuoteStep;
99	  const basePremium = sumOfItemPremiums(quote.items);
100	  const premiumAfterPercentageModifiers =
101	    basePremium + percent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
102	  return {
103	    results: [
104	      { premium: Math.ceil(premiumAfterPercentageModifiers + PROCESSING_FEE) },
105	    ],
106	  };
107	};
